/**
 * Unit tests for GrayPaintScale.getPaint(double)
 */
public class GrayPaintScale_getPaint_TriageGen2Test {

    @Test
    public void testGetPaint_LowerBound() {
        double lower = 0.0;
        double upper = 100.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // Test exactly at lower bound (g should be 0)
        Paint paint = scale.getPaint(lower);
        assertEquals(new Color(0, 0, 0), paint);
    }

    @Test
    public void testGetPaint_UpperBound() {
        double lower = 0.0;
        double upper = 100.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // Test exactly at upper bound (g should be 255)
        Paint paint = scale.getPaint(upper);
        assertEquals(new Color(255, 255, 255), paint);
    }

    @Test
    public void testGetPaint_MidRange() {
        double lower = 0.0;
        double upper = 100.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // Test middle value (50/100 * 255 = 127.5 -> cast to int is 127)
        Paint paint = scale.getPaint(50.0);
        assertEquals(new Color(127, 127, 127), paint);
    }

    @Test
    public void testGetPaint_BelowLowerBound() {
        double lower = 10.0;
        double upper = 20.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // Test value below lower bound (v should be clamped to lowerBound)
        // (10-10)/(20-10) * 255 = 0
        Paint paint = scale.getPaint(5.0);
        assertEquals(new Color(0, 0, 0), paint);
    }

