    @Test
    public void testGetPaint_Precision() {
        double lower = 0.0;
        double upper = 1.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // Test specific floating point precision
        // (0.5 - 0) / (1 - 0) * 255 = 127.5 -> 127
        Paint paint = scale.getPaint(0.5);
        assertEquals(new Color(127, 127, 127), paint);
